{
  "selections": [
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '뭘 해도 부족했던 것 같아요'라고 직접 표현했고, 아버지의 칭찬 없는 양육이 이 핵심 신념의 뿌리임. 상담사가 '잘했다'는 말 한마디를 스스로에게 해본다는 질문을 한 것은 바로 이 '결코 충분하지 않다'는 신념을 건드리고 있음."
    },
    {
      "trait_id": "/intermediate_beliefs/rule",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '가만히 있으면 불안해서 밀린 걸 찾아 한다'고 한 것은 '쉬는 것은 자격을 갖춘 다음의 일'이라는 규칙이 작동하는 모습. 일요일 드라이브를 거절하고 노트북을 편 상황 사례가 이 규칙의 구체적 예시임."
    },
    {
      "trait_id": "/intermediate_beliefs/assumption_negative",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 '제가 안 붙잡고 있으면 다 엉망이 될 것 같다', '제가 그 정도밖에 안 되는 사람이라는 걸 다들 볼 것 같다'고 한 것이 이 부정적 가정과 정확히 일치. 아버지의 실망한 표정이 그 '다들'의 원형임."
    },
    {
      "trait_id": "/coping_strategies/3",
      "background_ids": ["/situations/3"],
      "relevance": "상담사가 '스스로에게 잘했다고 말해본다는 게 어떤 느낌일 것 같으세요'라고 질문한 것은, 내담자가 자신의 성과를 깎아내리는 방식(칭찬을 '아직 멀었다'로 넘기는 패턴)을 의식적으로 멈추게 하려는 시도. 29장의 만족 설문 중 1장만 복기한 사례가 이 전략의 구체적 예시임."
    },
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data"],
      "relevance": "아버지가 98점에 '2점은 왜 틀렸냐'고 추궁하고 100점에 '유난 떨 것 없다'고 한 것이 엄격한 기준과 과잉비판 스키마의 형성 맥락. 내담자가 '늘 부족했던 것 같다'고 한 것은 이 스키마가 작동하는 현 모습임."
    },
    {
      "trait_id": "/coping_strategies/2",
      "background_ids": ["/situations/2"],
      "relevance": "내담자가 '쉬는 날이 생겨도 가만히 있으면 불안해서 밀린 걸 찾아 한다'고 한 진술이 이 대처 전략과 직접 연결됨. 남편의 '쉬는 법을 모른다'는 말도 이 패턴을 외부에서 관찰한 것."
    }
  ]
}

